public int lengthOfLIS(int[] nums) {
        int[] tails = new int[nums.length];
        int tail = 0;
        for (int i = 0; i < nums.length; i++) {
            int index = find(tails, tail, nums[i]);
            if (index < tail) {
                tails[index] = nums[i];
            } else {
                tails[tail] = nums[i];
                tail++;
            }
        }
        return tail;
    }

    private int find(int[] tails, int end, int num) {
        int l = -1, r = end + 1;
        while (l + 1 < r) {
            int mid = l + (r - l) / 2;
            if (tails[mid] < num) {
                l = mid;
            } else {
                r = mid;
            }
        }
        return r;
    }

